    // ═══════════════════════════════════════════════════════════════════════
    // ALBERS USA: BOUNDARY-EXACT ROUTING THRESHOLDS
    // ═══════════════════════════════════════════════════════════════════════

    /// Albers USA: exactly at lat=49.5, lon=-127.5 — Alaska branch requires
    /// lat > 49.5 AND lon < -127.5, so exactly at boundary should NOT enter Alaska.
    #[test]
    fn bug_hunt_albers_usa_exactly_at_alaska_boundary() {
        // Exactly at boundary: lat=49.5 is NOT > 49.5, so continental
        let (x_boundary, _) = albers_usa_fwd(-130.0, 49.5);
        let (x_continental, _) = albers_conic_fwd(-130.0, 49.5, 29.5, 45.5, 38.0, -96.0);
        assert!((x_boundary - x_continental).abs() < 1e-12,
            "lat=49.5 should NOT enter Alaska branch (needs > 49.5)");
    }

    /// Albers USA: exactly at lat=49.501 with lon < -127.5 SHOULD enter Alaska.
    #[test]
    fn bug_hunt_albers_usa_just_above_alaska_threshold() {
        let (x_above, _) = albers_usa_fwd(-130.0, 49.501);
        let (x_continental, _) = albers_conic_fwd(-130.0, 49.501, 29.5, 45.5, 38.0, -96.0);
        // Should differ because it entered Alaska branch
        assert!((x_above - x_continental).abs() > 0.01,
            "lat=49.501 with lon<-127.5 should enter Alaska branch");
    }

    /// Albers USA: lon exactly at -127.5 with lat>49.5 should NOT enter Alaska
    /// (condition is lon < -127.5, not <=).
    #[test]
    fn bug_hunt_albers_usa_alaska_lon_boundary() {
        let (x_boundary, _) = albers_usa_fwd(-127.5, 60.0);
        let (x_continental, _) = albers_conic_fwd(-127.5, 60.0, 29.5, 45.5, 38.0, -96.0);
        assert!((x_boundary - x_continental).abs() < 1e-12,
            "lon=-127.5 should NOT enter Alaska branch (needs < -127.5)");
    }

    /// Albers USA: Hawaii lower boundary: lat=18.0 is NOT > 18.0, so should
    /// NOT enter Hawaii branch.
    #[test]
    fn bug_hunt_albers_usa_hawaii_lat_lower_boundary() {
        let (x_boundary, _) = albers_usa_fwd(-160.0, 18.0);
        let (x_continental, _) = albers_conic_fwd(-160.0, 18.0, 29.5, 45.5, 38.0, -96.0);
        assert!((x_boundary - x_continental).abs() < 1e-12,
            "lat=18.0 should NOT enter Hawaii branch (needs > 18.0)");
    }

    /// Albers USA: Hawaii upper boundary: lat=24.0 is NOT < 24.0, so should
    /// NOT enter Hawaii branch.
    #[test]
    fn bug_hunt_albers_usa_hawaii_lat_upper_boundary() {
        let (x_boundary, _) = albers_usa_fwd(-160.0, 24.0);
        let (x_continental, _) = albers_conic_fwd(-160.0, 24.0, 29.5, 45.5, 38.0, -96.0);
        assert!((x_boundary - x_continental).abs() < 1e-12,
            "lat=24.0 should NOT enter Hawaii branch (needs < 24.0)");
    }

    /// Albers USA: point in neither Alaska nor Hawaii region: falls to continental.
    /// For example: lat=30, lon=-100 (Texas). Should not match any inset.
    #[test]
    fn bug_hunt_albers_usa_texas_goes_continental() {
        let (x, y) = albers_usa_fwd(-100.0, 30.0);
        let (cx, cy) = albers_conic_fwd(-100.0, 30.0, 29.5, 45.5, 38.0, -96.0);
        assert!((x - cx).abs() < 1e-12 && (y - cy).abs() < 1e-12,
            "Texas should use continental conic");
    }

