    // ═══════════════════════════════════════════════════════════════════════

    /// Mercator inverse with y=infinity: exp(inf) = inf, atan(inf) = pi/2,
    /// so lat = 2*(pi/2) - pi/2 = pi/2 = 90 degrees. Should not panic.
    #[test]
    fn bug_hunt_mercator_inv_inf_y_no_panic() {
        let (lon, lat) = mercator_inv(0.0, f64::INFINITY);
        assert!(lon.is_finite(), "mercator inv: inf y should give finite lon, got {lon}");
        // lat = to_deg(2*atan(exp(inf)) - pi/2) = to_deg(2*pi/2 - pi/2) = to_deg(pi/2) = 90
        assert!((lat - 90.0).abs() < 1e-6,
            "mercator inv: inf y should give lat=90, got {lat}");
    }

    /// Natural Earth inverse with very large y: Newton-Raphson may not converge.
    #[test]
    fn bug_hunt_natural_earth_inv_large_y_no_panic() {
        let (lon, lat) = natural_earth_inv(0.0, 100.0);
        // May not converge to anything sensible, but must not panic
        let _ = (lon, lat);
    }

    /// Equal Earth inverse with large y outside normal range.
    #[test]
    fn bug_hunt_equal_earth_inv_large_y_no_panic() {
        let (lon, lat) = equal_earth_inv(0.0, 100.0);
        // Must not panic; result may be NaN or nonsensical
        let _ = (lon, lat);
    }

