    // ═══════════════════════════════════════════════════════════════════════

    /// Natural Earth should have y-antisymmetry: y(lat) = -y(-lat) for any lon.
    #[test]
    fn bug_hunt_natural_earth_y_antisymmetry() {
        for lat in [10.0, 30.0, 60.0, 85.0] {
            let (_, y_pos) = natural_earth_fwd(0.0, lat);
            let (_, y_neg) = natural_earth_fwd(0.0, -lat);
            assert!((y_pos + y_neg).abs() < 1e-12,
                "natural-earth y should be antisymmetric: y({lat})={y_pos}, y({})={y_neg}",
                -lat);
        }
    }

    /// Natural Earth should have x-antisymmetry: x(lon) = -x(-lon) for any lat.
    #[test]
    fn bug_hunt_natural_earth_x_antisymmetry() {
        for lon in [10.0, 90.0, 180.0] {
            let (x_pos, _) = natural_earth_fwd(lon, 45.0);
            let (x_neg, _) = natural_earth_fwd(-lon, 45.0);
            assert!((x_pos + x_neg).abs() < 1e-12,
                "natural-earth x should be antisymmetric: x({lon})={x_pos}, x({})={x_neg}",
                -lon);
        }
    }

    // ═══════════════════════════════════════════════════════════════════════
    // ORTHOGRAPHIC: BOUNDARY CONDITION (cos_phi * cos_lam = 0 exactly)
    // ═══════════════════════════════════════════════════════════════════════

    /// When cos_phi * cos(lam) = exactly 0.0, the guard `< 0.0` is false,
    /// so we should get finite output. At lat=90, cos_phi = cos(pi/2) ~= 0,
    /// so the guard product is ~0 regardless of lon.
    #[test]
    fn bug_hunt_orthographic_pole_with_various_lon() {
        // At lat=90, cos(phi) ~ 0, so x ~ 0 regardless of lon
        for lon in [-180.0, -90.0, 0.0, 90.0, 180.0] {
            let (x, y) = orthographic_fwd(lon, 90.0);
            // Due to floating point, cos(pi/2) is not exactly 0 but ~6.12e-17
            // For lon=180: cos(pi) = -1, so cos_phi*cos_lam ~ -6.12e-17 < 0 → NaN!
            // This is actually correct behavior for lon=180 at lat=90
            if x.is_nan() {
                // Only acceptable for lon where cos(lam) < 0
                let cos_lam = to_rad(lon).cos();
                assert!(cos_lam < 0.0 || cos_lam.abs() < 1e-10,
                    "orthographic NaN at lat=90, lon={lon} with cos(lam)={cos_lam}");
            } else {
                assert!(x.is_finite() && y.is_finite(),
                    "orthographic at lat=90, lon={lon} should be finite, got ({x}, {y})");
            }
        }
    }

