    /// Mercator round-trip at 10-degree latitude increments.
    #[test]
    fn bug_hunt_mercator_wide_round_trip() {
        for lat in (-80..=80).step_by(10) {
            let lat = lat as f64;
            let lon = 45.0;
            let (x, y) = mercator_fwd(lon, lat);
            let (lon2, lat2) = mercator_inv(x, y);
            assert!((lon2 - lon).abs() < 1e-10,
                "mercator round-trip lon at lat={lat}: {lon} -> {lon2}");
            assert!((lat2 - lat).abs() < 1e-10,
                "mercator round-trip lat at lat={lat}: {lat} -> {lat2}");
        }
    }

