    // ═══════════════════════════════════════════════════════════════════════

    /// Equal Earth at lon=360 (wrapping). The projection does not wrap —
    /// it should just produce x = 2 * x(180), linearly scaled.
    #[test]
    fn bug_hunt_equal_earth_lon_360_is_double_180() {
        let (x180, _) = equal_earth_fwd(180.0, 0.0);
        let (x360, _) = equal_earth_fwd(360.0, 0.0);
        // x is linear in lambda, so x(360) should be exactly 2*x(180)
        assert!((x360 - 2.0 * x180).abs() < 1e-10,
            "equal-earth: x(360) should be 2*x(180), got x360={x360}, 2*x180={}",
            2.0 * x180);
    }

