    // ee_x_factor CORRECTNESS
    // ═══════════════════════════════════════════════════════════════════════

    /// ee_x_factor at t2=0 should return EE_A[0].
    #[test]
    fn bug_hunt_ee_x_factor_at_zero() {
        let val = ee_x_factor(0.0);
        assert!((val - EE_A[0]).abs() < 1e-15,
            "ee_x_factor(0) should be EE_A[0]={}, got {val}", EE_A[0]);
    }

    /// ee_x_factor with t2=1 (theta=1 radian): verify against hand computation.
    #[test]
    fn bug_hunt_ee_x_factor_at_one() {
        // t2=1, t4=1, t6=1, t8=1
        let expected = EE_A[0] + EE_A[1] + EE_A[2] + EE_A[3] + EE_A[4];
        let actual = ee_x_factor(1.0);
        assert!((actual - expected).abs() < 1e-15,
            "ee_x_factor(1) should be sum(EE_A)={expected}, got {actual}");
    }

    // ═══════════════════════════════════════════════════════════════════════
