        let (x, y) = orthographic_fwd(120.0, 60.0);
        // cos(60°) = 0.5, cos(120° in rad) = cos(2pi/3) = -0.5
        // cos_phi * cos_lam = 0.5 * (-0.5) = -0.25 < 0 → NaN
